use crate::{app::{App,PaneContent},model::RowState}; use ratatui::{Frame,widgets::{Paragraph,Block,Borders}}; 
pub fn draw(f:&mut Frame<'_>,a:&App){let area=f.area();if area.width<40||area.height<12{f.render_widget(Paragraph::new(format!("Terminal too small\n\nCerebro needs at least\n40 columns x 12 rows.\n\nCurrent size: {} x {}.\n\nResize the terminal,\nor press q/Esc/Ctrl-C to quit.",area.width,area.height)),area);return} let mut s="Cerebro — read-only\n\n".to_string();match &a.fleet.content{PaneContent::Loading=>s.push_str("Loading fleet...\n"),PaneContent::Fresh{value,..}|PaneContent::Stale{value,..}=>{s.push_str(&format!("Fleet {}\n",value.len()));for r in value{s.push_str(&format!("{}  {}  {:?}  {}\n",r.name,r.role,r.state,r.bead.as_deref().unwrap_or("-")));}},PaneContent::Unavailable{error,..}=>s.push_str(&format!("Fleet unavailable\n{}\nPress g to retry.\n",error))}s.push_str("\nWork\n");f.render_widget(Paragraph::new(s).block(Block::default().borders(Borders::ALL)),area)}
